magazine-cover.variantCss:
/* ============ 焦点：magazine-cover 报头封面 ============ */
.wemd-magazine-cover[data-variant="retro-newspaper"] {
  margin: 0 0 24px;
  padding: 20px 18px;
  text-align: center;
  border: 1px solid #c9b98f;
  background: #ece2cf;
}
.wemd-magazine-cover[data-variant="retro-newspaper"] .wemd-mc-rule-top,
.wemd-magazine-cover[data-variant="retro-newspaper"] .wemd-mc-rule-bottom {
  display: block;
  height: 0;
  border-top: 3px double #2b2118;
  margin: 0 0 12px;
}
.wemd-magazine-cover[data-variant="retro-newspaper"] .wemd-mc-rule-bottom {
  margin: 12px 0 0;
}
.wemd-magazine-cover[data-variant="retro-newspaper"] .wemd-mc-title {
  font-size: 26px;
  font-weight: 900;
  letter-spacing: 0.04em;
  color: #2b2118;
  line-height: 1.3;
}
.wemd-magazine-cover[data-variant="retro-newspaper"] .wemd-mc-title strong {
  color: #9e1f12;
  font-weight: 900;
}
.wemd-magazine-cover[data-variant="retro-newspaper"] .wemd-mc-subtitle {
  margin-top: 6px;
  font-size: 12px;
  letter-spacing: 0.22em;
  color: #6b5f4d;
  text-transform: uppercase;
}
.wemd-magazine-cover[data-variant="retro-newspaper"] .wemd-mc-divider {
  /* 共享把它做成 4px 红条（width/height/background），本主题用作文字分隔（—— 或 · · ·），
     需覆盖掉共享红条，否则出现「红条 + 内嵌 hr」双线。 */
  width: auto;
  height: auto;
  background: none;
  border-radius: 0;
  margin: 12px 0;
  font-size: 12px;
  color: #9e1f12;
  letter-spacing: 0.3em;
}
.wemd-magazine-cover[data-variant="retro-newspaper"] .wemd-mc-desc {
  margin-top: 10px;
  font-size: 14px;
  color: #6b5f4d;
  line-height: 1.7;
}

quote-card.variantCss:
/* ============ 焦点：quote-card 红竖条引用 ============ */
.wemd-quote-card[data-variant="retro-newspaper"] {
  margin: 20px 0;
  padding: 14px 16px;
  background: #ece2cf;
  border-left: 4px solid #9e1f12;
}
.wemd-quote-card[data-variant="retro-newspaper"] .wemd-qc-mark {
  display: block;
  font-family: Georgia, serif;
  font-size: 34px;
  line-height: 1;
  color: #9e1f12;
}
.wemd-quote-card[data-variant="retro-newspaper"] .wemd-qc-quote {
  margin: 6px 0 8px;
  font-size: 16px;
  font-style: italic;
  font-weight: 600;
  color: #2b2118;
  line-height: 1.7;
}
.wemd-quote-card[data-variant="retro-newspaper"] .wemd-qc-author {
  font-family: "Courier New", Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.22em;
  color: #6b5f4d;
  text-transform: uppercase;
}

end-card.variantCss:
/* ============ 焦点：end-card 报尾刊号 ============ */
.wemd-end-card[data-variant="retro-newspaper"] {
  margin: 28px 0 0;
  padding: 14px 16px 18px;
  text-align: center;
  border-top: 2px solid #2b2118;
  border-bottom: 1px solid #c9b98f;
}
.wemd-end-card[data-variant="retro-newspaper"] .wemd-ec-rule {
  display: block;
  height: 0;
  border-top: 1px solid #c9b98f;
  margin-bottom: 14px;
}
.wemd-end-card[data-variant="retro-newspaper"] .wemd-ec-title {
  font-size: 18px;
  font-weight: 900;
  letter-spacing: 0.08em;
  color: #2b2118;
}
.wemd-end-card[data-variant="retro-newspaper"] .wemd-ec-title strong {
  color: #9e1f12;
  font-weight: 900;
}
.wemd-end-card[data-variant="retro-newspaper"] .wemd-ec-subtitle {
  margin-top: 6px;
  font-family: "Courier New", Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.2em;
  color: #6b5f4d;
  text-transform: uppercase;
}
.wemd-end-card[data-variant="retro-newspaper"] .wemd-ec-deco {
  margin-top: 10px;
  font-size: 12px;
  color: #9e1f12;
}

stats-block.variantCss:
