  color: #6b5f4d;
  letter-spacing: 0.1em;
}

callout-pro.variantCss:
.wemd-callout-pro[data-variant="retro-newspaper"] {
  margin: 18px 0;
  padding: 14px 16px;
  background: #ece2cf;
  border-left: 3px solid #9e1f12;
  border-top: 1px solid #c9b98f;
  border-bottom: 1px solid #c9b98f;
  border-right: 1px solid #c9b98f;
}
.wemd-callout-pro[data-variant="retro-newspaper"] .wemd-component-body p {
  font-size: 14px;
}

section-title.variantCss:
/* ============ Content：section-title 报纸栏目标题 ============ */
.wemd-section-title[data-variant="retro-newspaper"] {
  /* 共享把它做成卡片（bg + 左边条 + 圆角 + padding），本主题用作报纸栏目标题（文字 + 下红线），
     需清掉共享卡片，否则出现「卡片底 + 左红条 + 下红线」三重样式。 */
  background: transparent;
  border-left: none;
  border-radius: 0;
  padding: 0 0 6px;
  margin: 26px 0 12px;
  border-bottom: 2px solid #9e1f12;
}
.wemd-section-title[data-variant="retro-newspaper"] .wemd-component-body {
  font-size: 19px;
  font-weight: 800;
  color: #2b2118;
  line-height: 1.4;
}

numbered-heading.variantCss:
/* ============ Content：numbered-heading 编号标题 ============ */
.wemd-numbered-heading[data-variant="retro-newspaper"] {
  margin: 24px 0 12px;
  padding-bottom: 6px;
  border-bottom: 1px solid #c9b98f;
}
.wemd-numbered-heading[data-variant="retro-newspaper"] .wemd-component-body {
  font-size: 18px;
  font-weight: 800;
  color: #2b2118;
  line-height: 1.4;
}

section-divider.variantCss:
/* ============ 焦点：section-divider 栏目分隔带 ============ */
.wemd-section-divider[data-variant="retro-newspaper"] {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 28px 0 18px;
}
.wemd-section-divider[data-variant="retro-newspaper"] .wemd-sd-part {
  font-family: "Courier New", Consolas, monospace;
  font-size: 11px;
  letter-spacing: 0.14em;
  color: #6b5f4d;
  white-space: nowrap;
}
.wemd-section-divider[data-variant="retro-newspaper"] .wemd-sd-line {
  flex: 1;
  height: 0;
  border-top: 1px solid #c9b98f;
}
.wemd-section-divider[data-variant="retro-newspaper"] .wemd-sd-title {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: #9e1f12;
  white-space: nowrap;
  text-transform: uppercase;
}

image-card.variantCss:
/* ============ Content：image-card 图片卡 ============ */
.wemd-image-card[data-variant="retro-newspaper"] {
  margin: 18px 0;
  padding: 6px;
  background: #ece2cf;
  border: 1px solid #c9b98f;
}
.wemd-image-card[data-variant="retro-newspaper"] .wemd-ic-image img {
  border-radius: 0;
}
.wemd-image-card[data-variant="retro-newspaper"] .wemd-ic-caption {
  margin-top: 8px;
  font-family: "Courier New", Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.14em;
  color: #6b5f4d;
}

text-card.variantCss:
/* ============ Content：text-card 正文卡（纸底细线） ============ */
.wemd-text-card[data-variant="retro-newspaper"] {
  margin: 18px 0;
  padding: 16px;
  background: #ece2cf;
  border: 1px solid #c9b98f;
}
.wemd-text-card[data-variant="retro-newspaper"] .wemd-component-body p {
  margin: 0 0 10px;
}

timeline.variantCss:
/* ============ Content：timeline 时间线 ============ */
.wemd-timeline[data-variant="retro-newspaper"] {
  margin: 18px 0;
  padding: 14px 16px;
  background: #ece2cf;
  border: 1px solid #c9b98f;
}
.wemd-timeline[data-variant="retro-newspaper"] .wemd-tl-title {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: #9e1f12;
  margin-bottom: 10px;
}
.wemd-timeline[data-variant="retro-newspaper"] .wemd-tl-item {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 4px 0;
}
.wemd-timeline[data-variant="retro-newspaper"] .wemd-tl-dot {
  /* 共享圆点已做尺寸无关居中（left:-21px + translateX(-50%)），圆心自动落在竖线中心，
     与尺寸无关。这里只需改尺寸与颜色，不要自己写 left（会破坏居中）。 */
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #9e1f12;
  border: none; /* 实心红点：去掉共享白底红环 */
}
.wemd-timeline[data-variant="retro-newspaper"] .wemd-tl-text {
  font-size: 14px;
  color: #2b2118;
}

styled-table.variantCss:
/* ============ 焦点：styled-table 报纸表格 ============ */
.wemd-styled-table[data-variant="retro-newspaper"] {
  margin: 18px 0;
  border: 1px solid #2b2118;
}
.wemd-styled-table[data-variant="retro-newspaper"] .wemd-sbt-table table th {
  background: #2b2118;
  color: #f5efe0;
  font-family: "Helvetica Neue", Arial, "PingFang SC", sans-serif;
  font-size: 12px;
  letter-spacing: 0.14em;
  padding: 9px 10px;
  text-align: left;
  font-weight: 700;
}
.wemd-styled-table[data-variant="retro-newspaper"] .wemd-sbt-table table td {
  font-size: 13px;
  padding: 8px 10px;
  color: #2b2118;
  border: none;
  border-bottom: 1px solid #c9b98f;
  background: transparent;
}
.wemd-styled-table[data-variant="retro-newspaper"] .wemd-sbt-table table td strong {
  color: #9e1f12;
  font-weight: 700;
}

code-frame.variantCss:
/* ============ Content：code-frame 代码（纸底深字） ============ */
.wemd-code-frame[data-variant="retro-newspaper"] {
  margin: 18px 0;
  border: 1px solid #c9b98f;
  background: #ece2cf;
}
.wemd-code-frame[data-variant="retro-newspaper"] .wemd-cf-title {
  padding: 8px 12px;
  font-family: "Courier New", Consolas, monospace;
  font-size: 11px;
  letter-spacing: 0.12em;
  color: #6b5f4d;
  background: #e2d7bd;
  border-bottom: 1px solid #c9b98f;
}
.wemd-code-frame[data-variant="retro-newspaper"] .wemd-cf-code pre {
  margin: 0;
  padding: 14px 16px;
  overflow-x: auto;
  font-family: "Courier New", Consolas, monospace;
  font-size: 13px;
  line-height: 1.8;
  color: #2b2118;
  background: transparent;
}
.wemd-code-frame[data-variant="retro-newspaper"] .wemd-cf-code pre code {
  background: transparent;
  color: #2b2118;
}

pullquote.variantCss:
/* 共享 pullquote 根元素自带 border-left:5px + 卡片底/圆角；主题用 body 的
   border-left 表达竖条，必须覆盖根元素去掉共享竖条，否则根 + body 双条。 */
.wemd-pullquote[data-variant="retro-newspaper"] {
  background: transparent;
  border-left: none;
  border-radius: 0;
  padding: 0;
}
.wemd-pullquote[data-variant="retro-newspaper"] .wemd-component-body {
  margin: 18px 0;
  padding: 10px 14px;
  border-left: 4px solid #9e1f12;
  font-size: 16px;
  font-style: italic;
  font-weight: 600;
  color: #2b2118;
  background: transparent;
}

divider-fancy.variantCss:
/* ============ 焦点：divider-fancy 菱形分隔 ============ */
.wemd-divider-fancy[data-variant="retro-newspaper"] {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 20px 0;
  color: #9e1f12;
}
.wemd-divider-fancy[data-variant="retro-newspaper"] .wemd-df-label {
  /* 共享 .wemd-df-label 有 width:100%（共享结构把线嵌在 label 内），
     本主题自定义骨架把线放在 label 两侧，须把 width 归 auto，否则 label 独占整行 */
  width: auto;
  font-size: 11px;
  letter-spacing: 0.24em;
  color: #6b5f4d;
  text-transform: uppercase;
  white-space: nowrap;
}
.wemd-divider-fancy[data-variant="retro-newspaper"] .wemd-df-line {
  flex: 1;
  height: 0;
  border-top: 1px solid #c9b98f;
}
.wemd-divider-fancy[data-variant="retro-newspaper"] .wemd-df-glyph {
  font-size: 11px;
  color: #9e1f12;
}

divider.variantCss:
.wemd-divider[data-variant="retro-newspaper"] {
  margin: 22px 0;
}
.wemd-divider[data-variant="retro-newspaper"] .wemd-component-body {
  height: 0;
  border-top: 1px solid #c9b98f;
  border-bottom: 1px solid #c9b98f;
  padding: 2px 0;
  color: transparent;
}
/* markdown 的 --- 会在 divider body 内生成 <hr>，双线中间会多出一条 hr 线（三线）。
   隐藏它，只留主题的上下双线。 */
.wemd-divider[data-variant="retro-newspaper"] .wemd-component-body hr {
  display: none;
}

copyright-notice.variantCss:
/* ============ Utility：copyright-notice 版权 ============ */
.wemd-copyright-notice[data-variant="retro-newspaper"] .wemd-component-body {
  margin: 20px 0 0;
  padding-top: 10px;
  border-top: 1px solid #c9b98f;
  font-family: "Courier New", Consolas, monospace;
  font-size: 10px;
  letter-spacing: 0.14em;
  color: #8a7a63;
  text-align: center;
}
